import { Database } from "bun:sqlite";
import { fileURLToPath } from "node:url";
import { type BunSQLiteDatabase, drizzle } from "drizzle-orm/bun-sqlite";
import { migrate } from "drizzle-orm/bun-sqlite/migrator";
import * as schema from "./schema.ts";

/** Migrations are generated by drizzle-kit into packages/db/migrations. */
export const migrationsFolder = fileURLToPath(new URL("../migrations", import.meta.url));

export type DatabaseHandle = {
  sqlite: Database;
  db: BunSQLiteDatabase<typeof schema>;
};

export function openDatabase(path: string): DatabaseHandle {
  const sqlite = new Database(path, { create: true });
  sqlite.exec("PRAGMA journal_mode = WAL;");
  sqlite.exec("PRAGMA foreign_keys = ON;");
  return { sqlite, db: drizzle(sqlite, { schema }) };
}

/** Apply pending migrations. Idempotent — safe to call on every startup. */
export function runMigrations(db: BunSQLiteDatabase<typeof schema>): void {
  migrate(db, { migrationsFolder });
}
